// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('failed clipboard export surfaces an error to the user', async ({ page }) => {
    test.setTimeout(133000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');
    await page.locator('[data-testid="toolbar-rectangle"]').waitFor({ state: 'visible', timeout: 10000 });
    // The toolbar radio is visually hidden and its icon subtree intercepts pointer
    // events, so select the rectangle tool via its keyboard shortcut.
    await page.keyboard.press("r");
    await page.mouse.move(500, 300);
    await page.mouse.down();
    await page.mouse.move(750, 470, { steps: 10 });
    await page.mouse.up();
    await page.keyboard.press("Control+Shift+E");
    await expect(page.getByRole("heading", { name: "Export image" }).last()).toBeVisible();
    const copyButton = page.getByRole("button", { name: "Copy PNG to clipboard" });
    // "Copy PNG to clipboard" only renders when the browser reports clipboard-blob
    // support (probablySupportsClipboardBlob || isFirefox).
    test.skip(await copyButton.count() === 0, 'browser does not expose clipboard-blob export');
    await page.evaluate(() => {
  Object.defineProperty(navigator, 'clipboard', {
    configurable: true,
    value: {
      write: () => Promise.reject(new Error('Clipboard write denied')),
      writeText: () => Promise.reject(new Error('Clipboard write denied')),
    },
  });
  return 'clipboard write forced to fail';
});
    await copyButton.click();
    // A failing clipboard export must never be silent.
    await expect(page.getByRole("heading", { name: "Error" })).toBeVisible();
    await expect(page.getByText("Couldn't copy to clipboard.")).toBeVisible();
});
